begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(10);
select has_table('public','employees','Employee records exist');
select is((select count(*)::int from pg_tables where schemaname='public' and rowsecurity and tablename in
 ('permissions','business_roles','business_role_permissions','employees','employee_branches','employee_salary_settings','employee_salary_history','employee_invitations')),8,'All employee/role/salary/invitation tables have RLS');
select ok(not has_table_privilege('authenticated','public.employee_salary_settings','select'),'Salary table is not exposed directly');
select ok(not has_table_privilege('authenticated','public.employees','update'),'Employee writes require checked RPC');
create temporary table employee_test_scope(label text primary key,id uuid);
grant select,insert on employee_test_scope to authenticated;
insert into auth.users(id,email) values('88880000-0000-0000-0000-000000000001','employee-pgtap-a@example.test'),('88880000-0000-0000-0000-000000000002','employee-pgtap-b@example.test');
set local role authenticated;
set local request.jwt.claim.sub='88880000-0000-0000-0000-000000000001';
insert into employee_test_scope select 'a',public.create_business('Employee pgTAP A');
insert into employee_test_scope select 'branch',id from public.branches limit 1;
insert into employee_test_scope select 'employee',public.save_employee((select id from employee_test_scope where label='a'),null,'Offline employee','','','Teacher','active','2026-10-22','',array[(select id from employee_test_scope where label='branch')]);
select is((select user_id from public.employees limit 1),null::uuid,'Employee does not need a login');
select public.save_employee_salary((select id from employee_test_scope where label='a'),(select id from employee_test_scope where label='employee'),'fixed_monthly','9007199254740993.12','','','','','UZS','Initial salary');
select is(public.get_employee_salary((select id from employee_test_scope where label='a'),(select id from employee_test_scope where label='employee'))->>'amount','9007199254740993.12','Salary round-trips exactly');
set local request.jwt.claim.sub='88880000-0000-0000-0000-000000000002';
insert into employee_test_scope select 'b',public.create_business('Employee pgTAP B');
select is((select count(*)::int from public.employees),0,'B cannot read A employees');
select throws_ok($$select public.get_employee_salary((select id from employee_test_scope where label='a'),(select id from employee_test_scope where label='employee'))$$,'42501','Salary access denied','B cannot read A salary RPC');
select throws_ok($$select public.save_employee((select id from employee_test_scope where label='a'),(select id from employee_test_scope where label='employee'),'Forged','','','','active','2026-10-22','',array[(select id from employee_test_scope where label='branch')])$$,'42501','Employee update denied','Foreign ID mutation denied');
set local request.jwt.claim.sub='';
select is((select count(*)::int from public.employees),0,'No JWT subject sees no employees');
reset role;
select * from finish();
rollback;
